// Derivado do Foglamp (https://github.com/foglamp-labs/foglamp, apps/web/src/components/app/code-block.tsx @ 2bc3bb5), Apache-2.0.
// Modificado por joaodadas/lume: imports reescritos para @/registry/base-vega/* (Button de ui, CopyIcon de components, useCopied de hooks), aria-label "Copiar código"; as regras .shiki do index.css do Foglamp são injetadas pelo registry via campo css.
"use client";

import type * as React from "react";
import { useEffect, useState } from "react";
import { createHighlighterCore, type HighlighterCore } from "shiki/core";
import { createJavaScriptRegexEngine } from "shiki/engine/javascript";

import { CopyIcon } from "@/registry/base-vega/components/copy-icon";
import { useCopied } from "@/registry/base-vega/hooks/use-copied";
import { cn } from "@/registry/base-vega/lib/utils";
import { Button } from "@/registry/base-vega/ui/button";

// A copy-pasteable code block with Shiki syntax highlighting. Highlighting runs
// client-side and async; the raw code renders immediately as a fallback so there
// is never an empty flash. The highlighter is a lazy singleton (built once,
// shared by every CodeBlock) and uses the pure-JS regex engine — no wasm to
// load in the browser. Dual theme: `github-light` in light mode, `vesper` in
// dark; each token carries both as CSS variables, selected by the `.dark` class
// (see index.css).

// O CSS que escolhe o tema vem junto com o item code-block (campo css do
// registry) e cai no globals.css do consumidor:
//   .shiki { background-color: var(--shiki-light-bg) }
//   .shiki, .shiki span { color: var(--shiki-light) }
//   .dark .shiki { background-color: var(--shiki-dark-bg) }
//   .dark .shiki, .dark .shiki span { color: var(--shiki-dark) }
// Sem essas quatro regras o bloco renderiza, mas sem cor.

// Above this size highlighting is skipped and the plain <pre> fallback stays
// up: Shiki tokenizes on the main thread, and a multi-MB pretty-printed JSON
// payload would freeze the tab for seconds.
const HIGHLIGHT_MAX_CHARS = 50_000;

let highlighterPromise: Promise<HighlighterCore> | undefined;

function getHighlighter(): Promise<HighlighterCore> {
  if (!highlighterPromise) {
    highlighterPromise = createHighlighterCore({
      themes: [
        import("shiki/themes/github-light.mjs"),
        import("shiki/themes/vesper.mjs"),
      ],
      langs: [
        import("shiki/langs/typescript.mjs"),
        import("shiki/langs/json.mjs"),
      ],
      engine: createJavaScriptRegexEngine(),
    });
  }
  return highlighterPromise;
}

/**
 * Highlight `code` with Shiki, returning the dual-theme HTML string (or null
 * until the async highlighter resolves — render the raw text as a fallback so
 * there's never an empty flash). Shares the lazy singleton highlighter with
 * {@link CodeBlock}; `lang` must be one of its loaded grammars (typescript, json).
 */
export function useShikiHtml(code: string, lang = "typescript"): string | null {
  const [html, setHtml] = useState<string | null>(null);

  useEffect(() => {
    if (code.length > HIGHLIGHT_MAX_CHARS) {
      setHtml(null);
      return;
    }
    let active = true;
    void getHighlighter()
      .then((hl) => {
        const out = hl.codeToHtml(code, {
          lang,
          themes: { light: "github-light", dark: "vesper" },
          defaultColor: false,
        });
        if (active) setHtml(out);
      })
      .catch(() => {
        /* keep the plain-text fallback */
      });
    return () => {
      active = false;
    };
  }, [code, lang]);

  return html;
}

export function CodeBlock({
  code,
  lang = "typescript",
  actions,
  hideCopy = false,
}: {
  code: string;
  lang?: string;
  /** Extra controls rendered in the top-right corner, left of the copy button. */
  actions?: React.ReactNode;
  /** Render no corner controls — the parent overlays its own (e.g. shared
   * controls above crossfading blocks, so they don't fade with the code). */
  hideCopy?: boolean;
}) {
  const html = useShikiHtml(code, lang);
  const { copied, markCopied } = useCopied(2000);

  const copy = () => {
    void navigator.clipboard.writeText(code);
    markCopied();
  };

  return (
    <div
      className={cn(
        "relative text-left text-xs [&_pre]:m-0 [&_pre]:overflow-auto [&_pre]:rounded-md [&_pre]:bg-muted/50! [&_pre]:dark:bg-muted/20!  [&_pre]:p-5 [&_pre]:leading-relaxed [&_pre]:shadow-(--custom-shadow) corner-squircle",
        actions || hideCopy ? "[&_pre]:pt-5" : "[&_pre]:pr-10",
      )}
    >
      {html ? (
        // O HTML vem do Shiki a partir de `code`, que o chamador controla; não
        // é conteúdo de terceiros.
        // biome-ignore lint/security/noDangerouslySetInnerHtml: saída do Shiki
        <div dangerouslySetInnerHTML={{ __html: html }} />
      ) : (
        <pre className="bg-muted! dark:bg-muted! text-foreground">
          <code>{code}</code>
        </pre>
      )}
      {!hideCopy && (
        <div className="absolute right-3 top-3 flex items-center gap-1">
          {actions}
          <Button
            size="icon-sm"
            variant="outline"
            className="text-muted-foreground hover:text-foreground  dark:bg-input/20"
            aria-label="Copiar código"
            onClick={copy}
          >
            <CopyIcon copied={copied} />
          </Button>
        </div>
      )}
    </div>
  );
}
